/bin/bash -lc "node --input-type=module <<'EOF'
import { chromium } from '@playwright/test'

const browser = await chromium.launch({ headless: true })
const page = await browser.newPage()
const prefetchResponses = []
page.on('response', response => {
  if (response.url().includes('/catalog?category=')) {
    prefetchResponses.push({ url: response.url(), status: response.status(), prefetch: response.request().headers()['next-router-prefetch'] ?? null })
  }
})
await page.goto('http://127.0.0.1:3010/')
await page.waitForFunction(() => {
  const links = [...document.querySelectorAll('a[href"'^="/catalog?category="]'"')]
  return links.length === 2 && links.every(link => link.getAttribute('href'))
})
await page.waitForTimeout(2200)
console.log('Prefetch responses:', JSON.stringify(prefetchResponses))
for (const category of ['sale', 'featured']) {
  if (category === 'featured') {
    await page.goto('http://127.0.0.1:3010/')
    await page.waitForTimeout(2200)
  }
  await page.evaluate(() => {
    window.__sawLoading = false
    window.__loadingObserver = new MutationObserver(() => {
      if (document.body?.textContent?.includes('Loading category...')) window.__sawLoading = true
    })
    window.__loadingObserver.observe(document.body, { childList: true, subtree: true, characterData: true })
  })
  await page.locator("'`a[href="/catalog?category=${category}"]`).click()
  await page.waitForURL(`**/catalog?category=${category}`)
  const heading = await page.locator('"'main section h2').textContent()
  const products = await page.locator('main section li').allTextContents()
  const sawLoading = await page.evaluate(() => {
    window.__loadingObserver.disconnect()
    return window.__sawLoading
  })
  console.log(JSON.stringify({ category, heading, products, sawLoading }))
}
await browser.close()
EOF"

